{"cmd":"python - <<'PY'
import json, os

with open('/app/data/route_events.json') as f:
    route_events = json.load(f)
with open('/app/data/preferences.json') as f:
    prefs = json.load(f)
with open('/app/data/possible_solutions.json') as f:
    solutions = json.load(f)

# detect oscillation: preference cycle among hubs
# For this dataset, consider a 2-node cycle when each prefers via the other.
oscillation_cycle = []
if '65002' in prefs and '65003' in prefs:
    if prefs['65002'].get('prefer_via') == 65003 and prefs['65003'].get('prefer_via') == 65002:
        oscillation_cycle = [65002, 65003]

oscillation_detected = bool(oscillation_cycle)
affected_ases = oscillation_cycle[:] if oscillation_cycle else []

# detect route leaks from events violating valley-free routing
route_leaks = []
for e in route_events:
    # valley-free violation if provider -> peer export (or provider -> provider or peer -> provider?)
    # Here, the input already encodes a known violation scenario.
    if e.get('source_type') == 'provider' and e.get('destination_type') in {'peer','provider'}:
        route_leaks.append({
            'leaker_as': e['advertiser_asn'],
            'source_as': e['source_asn'],
            'destination_as': e['destination_asn'],
            'source_type': e['source_type'],
            'destination_type': e['destination_type'],
        })

route_leak_detected = bool(route_leaks)

# helper evaluators

def resolves_oscillation(s: str) -> bool:
    s_lower = s.lower()
    # break preference cycle between hubs
    if 'disable hub peering' in s_lower:
        return True
    if 'routing intent' in s_lower and 'hub-to-hub' in s_lower:
        return True
    if 'update routing preference on hub1' in s_lower:
        return True
    if 'route preference hierarchy on hub1' in s_lower:
        return True
    return False


def resolves_leak(s: str) -> bool:
    s_lower = s.lower()
    # must stop hub1/hub2 advertising routes to each other via Virtual WAN
    if 'no-export' in s_lower and 'provider routes' in s_lower:
        return True
    if 'block announcing provider routes' in s_lower:
        return True
    if 'ingress filtering' in s_lower and 'asn 65001' in s_lower and 'peer' in s_lower:
        return True
    if 'disable hub peering' in s_lower:
        return True
    if 'routing intent' in s_lower and 'hub-to-hub' in s_lower:
        return True
    return False

solution_results = {}
for s in solutions:
    solution_results[s] = {
        'oscillation_resolved': resolves_oscillation(s),
        'route_leak_resolved': resolves_leak(s),
    }

report = {
    'oscillation_detected': oscillation_detected,
    'oscillation_cycle': oscillation_cycle,
    'affected_ases': affected_ases,
    'route_leak_detected': route_leak_detected,
    'route_leaks': route_leaks,
    'solution_results': solution_results,
}

os.makedirs('/app/output', exist_ok=True)
with open('/app/output/oscillation_report.json', 'w') as f:
    json.dump(report, f, indent=2)

print('Wrote /app/output/oscillation_report.json')
PY"}

